def score(program: str) -> float:
    s = ''.join(program.split())
    n = len(s)
    if n == 0:
        return 0.0
    m = sum(map(ord, s)) / n
    p = sum(c in '()[]:,.=' for c in s) / n
    v = (m - 80) / 30 + p
    return max(0.0, min(0.6, v * 0.6))

def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)
    except Exception:
        return 0.0
    nodes = list(ast.walk(tree))
    kinds = {type(n).__name__ for n in nodes}
    subs = {ast.dump(n) for n in nodes}
    return (min(len(kinds), 30) / 30 + len(subs) / len(nodes)) / 2

import re
import zlib
def score(program: str) -> float:
    toks = set(re.findall(r"\w+", program)) or {"x"}
    mins = [min(zlib.crc32((s + t).encode()) for t in toks) for s in "abcdefghijklmnop"]
    return sum(mins) / len(mins) / 4294967296.0

